add_action( 'woocommerce_product_options_general_product_data', 'perfectpixel_hide_related_checkbox' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_hide_related_save' );
add_action( 'woocommerce_before_single_product', 'perfectpixel_hide_related_maybe' );

function perfectpixel_hide_related_checkbox() {
	echo '<div class="options_group">';
	woocommerce_wp_checkbox(
		array(
			'id'          => '_perfectpixel_hide_related',
			'label'       => 'Απόκρυψη σχετικών προϊόντων',
			'description' => 'Να μην εμφανίζονται «Σχετικά προϊόντα» σε αυτό το προϊόν',
		)
	);
	echo '</div>';
}

function perfectpixel_hide_related_save( $product ) {
	$product->update_meta_data( '_perfectpixel_hide_related', isset( $_POST['_perfectpixel_hide_related'] ) ? 'yes' : 'no' );
}

function perfectpixel_hide_related_maybe() {
	global $product;
	if ( $product && 'yes' === $product->get_meta( '_perfectpixel_hide_related' ) ) {
		remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_output_related_products', 20 );
	}
}
